def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 70
    MIN_SUPPLY = 15
    MAX_SUPPLY = 25

    supply = float(day_context['supply'])
    day = int(day_context['day'])
    hp = float(my_status['hp'])
    budget = float(my_status['budget'])
    no_water = int(my_status['no_water_days'])

    if budget <= 0:
        return 0.0

    alive_opps = []
    prev_bids = []
    urgent_opp = False
    rich_opp = False

    for opp_id, opp in opponents_status.items():
        if opp.get('alive'):
            alive_opps.append(opp)
            if float(opp.get('budget', 0)) > budget:
                rich_opp = True
            if int(opp.get('no_water_days', 0)) >= 2 or float(opp.get('hp', 0)) <= 3:
                urgent_opp = True
            prev = opp.get('previous_trace', {})
            if prev and prev.get('bid') is not None:
                try:
                    prev_bids.append(float(prev.get('bid', 0)))
                except Exception:
                    pass

    if not alive_opps:
        return min(budget, 18.0)

    max_prev = max(prev_bids) if prev_bids else 0.0
    avg_prev = (sum(prev_bids) / len(prev_bids)) if prev_bids else 0.0

    scarcity = (MAX_SUPPLY - supply) / float(MAX_SUPPLY - MIN_SUPPLY)
    if scarcity < 0:
        scarcity = 0.0
    if scarcity > 1:
        scarcity = 1.0

    my_urgent = no_water >= 2 or hp <= 3
    caution = no_water >= 1 or hp <= 6

    base = DAILY_SALARY * (0.32 + 0.28 * scarcity)

    if supply >= 23:
        base -= 8.0
    elif supply <= 17:
        base += 10.0

    if my_urgent:
        target = max(base + 28.0, max_prev + 4.0, DAILY_SALARY * 0.92)
    elif caution:
        target = max(base + 10.0, min(max_prev + 2.0, DAILY_SALARY * 0.95))
    else:
        if max_prev >= 130:
            target = base - 6.0
        elif max_prev >= 90:
            target = max(base, avg_prev * 0.72)
        else:
            target = max(base, max_prev + 1.5)

    if urgent_opp and not my_urgent:
        target -= 4.0
    if rich_opp and not my_urgent and max_prev > 110:
        target -= 5.0

    days_left = max(0, 10 - day)
    reserve = days_left * 14.0
    if budget < reserve:
        target *= 0.82
    if budget < 90:
        target = min(target, DAILY_SALARY * 0.72)

    if my_urgent and budget > 0:
        target = max(target, min(budget, DAILY_SALARY * 1.05))

    if target < 0:
        target = 0.0
    if target > budget:
        target = budget

    return float(round(target, 2))

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 9
    DAILY_SALARY = 90
    MIN_SUPPLY = 15
    MAX_SUPPLY = 25

    supply = float(day_context.get('supply', 0.0))
    day = int(day_context.get('day', 0))

    hp = int(my_status.get('hp', 0))
    budget = float(my_status.get('budget', 0.0))
    no_water_days = int(my_status.get('no_water_days', 0))

    alive_opponents = []
    for oid, o in opponents_status.items():
        if o.get('alive', False):
            alive_opponents.append(o)

    if not alive_opponents:
        return float(min(budget, DAILY_SALARY * 0.4))

    # Immediate reaction to yesterday bids
    yesterday_bids = []
    for o in alive_opponents:
        prev = o.get('previous_trace', {}) or {}
        b = prev.get('bid', None)
        if b is not None:
            try:
                yesterday_bids.append(float(b))
            except Exception:
                pass

    highest_prev_bid = max(yesterday_bids) if yesterday_bids else 0.0

    # Estimate how many full water units supply can buy
    # (Not used for indexing; only to scale aggressiveness)
    units = supply / float(WATER_REQ) if WATER_REQ else 0.0

    # Pressure logic: if others bid near/above daily salary yesterday, they likely contest today.
    # We keep a mid bid unless our HP is low.
    if highest_prev_bid >= DAILY_SALARY * 0.85:
        if hp <= 2 or no_water_days >= 1:
            bid = DAILY_SALARY * 0.95
        elif hp <= 3:
            bid = DAILY_SALARY * 0.75
        else:
            bid = DAILY_SALARY * 0.35
    else:
        # If yesterday bids were not extreme, bid enough to secure water but conserve budget.
        # Scale slightly with supply (more supply => can bid a bit less).
        supply_factor = (supply - MIN_SUPPLY) / (MAX_SUPPLY - MIN_SUPPLY) if MAX_SUPPLY > MIN_SUPPLY else 0.5
        supply_factor = max(0.0, min(1.0, supply_factor))
        bid = DAILY_SALARY * (0.55 - 0.15 * supply_factor)

    # If our HP is critically low, override to maximize chance.
    if hp <= 1:
        bid = DAILY_SALARY * 1.0

    # Convert to feasible bid bounds
    bid = float(min(budget, bid))
    if bid < 0.0:
        bid = 0.0
    return bid

